script:
(function () {
  'use strict';
  // US Treasury bill pricing (TreasuryDirect formulas).
  //   Price per $100:  P = 100 x (1 - d x t / 360)            d = discount rate, t = days to maturity
  //   Discount rate:   d = (100 - P) / 100 x 360 / t
  //   Investment rate (bond-equivalent yield), y = days in the year after issue (365 or 366):
  //     t <= y/2 (half a year or less):  i = (100 - P) / P x y / t
  //     t >  y/2: the positive root of (t/2y - 0.25) i^2 + (t/y) i + (P - 100)/P = 0, i.e.
  //       i = (-2t/y + 2 sqrt((t/y)^2 - (2t/y - 1)(1 - 100/P))) / (2t/y - 1)
  //   Price per $100 is rounded to 6 decimals, as Treasury publishes it.
  // Checked against TreasuryDirect's own example ($1,000 26-week bill at 0.145% = $999.27) and
  // against Treasury auction results (FiscalData auctions_query, Sept/Oct 2026), e.g.
  //   52-week 364 days 4.400% -> 95.551111, investment rate 4.616%
  //   26-week 182 days 4.285% -> 97.833694, investment rate 4.441%
  //   13-week  91 days 4.110% -> 98.961083, investment rate 4.211%
  //   4-week   28 days 3.850% -> 99.700556, investment rate 3.915%
  //   17-week 119 days 4.115% -> 98.639764, investment rate 4.230%
  // and the reverse (price -> discount rate) round-trips to the published rates.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var TERMS = [[28, '4 weeks'], [42, '6 weeks'], [56, '8 weeks'], [91, '13 weeks'], [119, '17 weeks'], [182, '26 weeks'], [364, '52 weeks']];

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function round6(x) { return Math.round(x * 1e6) / 1e6; }

  function priceFromRate(d, t) { return round6(100 * (1 - d * t / 360)); }

  function rateFromPrice(p, t) { return (100 - p) / 100 * 360 / t; }

  function investmentRate(p, t, y) {
    if (!(p > 0) || !(t > 0)) return NaN;
    if (t <= y / 2) return (100 - p) / p * y / t;
    var a = t / y, b = 2 * a - 1;
    var disc = a * a - b * (1 - 100 / p);
    if (disc < 0) return NaN;
    return (-2 * a + 2 * Math.sqrt(disc)) / b;
  }

  function effectiveYield(p, t) { return Math.pow(100 / p, 365 / t) - 1; }

  function pct(x, digits) { return isFinite(x) ? (x * 100).toFixed(digits) + '%' : '–'; }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clear(id) {
    var el = document.getElementById(id);
    while (el.firstChild) el.removeChild(el.firstChild);
    return el;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) {
      var td = document.createElement('td');
      td.textContent = text;
      tr.appendChild(td);
    });
    body.appendChild(tr);
  }

  function blank() {
    ['tbCost', 'tbInterest', 'tbInvest', 'tbApy', 'tbPer100', 'tbDisc', 'tbDaysOut', 'tbFaceOut', 'tbTermsRate'].forEach(function (id) { set(id, '–'); });
    clear('tbTerms');
  }

  function update() {
    var mode = document.getElementById('tbMode').value;
    var term = document.getElementById('tbTerm').value;
    document.getElementById('tbDaysWrap').hidden = term !== 'custom';
    document.getElementById('tbRateWrap').hidden = mode !== 'rate';
    document.getElementById('tbPriceWrap').hidden = mode !== 'price';

    var face = num('tbFace');
    var days = term === 'custom' ? num('tbDays') : parseInt(term, 10);
    var y = parseInt(document.getElementById('tbYear').value, 10) === 366 ? 366 : 365;
    var error = document.getElementById('tbError');
    var msg = '';
    if (isNaN(face) || face <= 0) msg = 'Enter a face value above $0.';
    else if (isNaN(days) || days < 1 || days > 366 || Math.round(days) !== days) msg = 'Enter whole days to maturity from 1 to 366.';

    var d, p;
    if (!msg && mode === 'rate') {
      d = num('tbRate') / 100;
      if (isNaN(d) || d < 0 || d > 1) msg = 'Enter a discount rate from 0 to 100%.';
      else {
        p = priceFromRate(d, days);
        if (!(p > 0)) msg = 'That discount rate is too high for this term: the price would be $0 or less.';
      }
    } else if (!msg) {
      p = num('tbPrice');
      if (isNaN(p) || p <= 0 || p > 100) msg = 'Enter a price above $0 and no more than $100 per $100 of face value.';
      else d = rateFromPrice(p, days);
    }

    error.hidden = !msg;
    if (msg) { error.textContent = msg; blank(); return; }

    var cost = Math.round(face * p) / 100;
    var inv = investmentRate(p, days, y);
    set('tbCost', money.format(cost));
    set('tbInterest', money.format(face - cost));
    set('tbInvest', pct(inv, 3));
    set('tbApy', pct(effectiveYield(p, days), 3));
    set('tbPer100', '$' + p.toFixed(6));
    set('tbDisc', pct(d, 3));
    set('tbDaysOut', days + (days === 1 ? ' day' : ' days'));
    set('tbFaceOut', money.format(face));

    set('tbTermsRate', 'a ' + pct(d, 3) + ' discount rate');
    var body = clear('tbTerms');
    TERMS.forEach(function (t) {
      var tp = priceFromRate(d, t[0]);
      if (!(tp > 0)) { addRow(body, [t[1], String(t[0]), '–', '–', '–', '–']); return; }
      var tc = Math.round(face * tp) / 100;
      addRow(body, [t[1], String(t[0]), '$' + tp.toFixed(6), money.format(tc), money.format(face - tc), pct(investmentRate(tp, t[0], y), 3)]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('tbForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
